import React, { useState } from 'react';
import Chatbot from 'react-chatbot-kit';
import 'react-chatbot-kit/build/main.css';

function Prediction() {
  // To store prediction response from backend
  const [predictionResult, setPredictionResult] = useState(null);

  // -------------------- ActionProvider --------------------
  class ActionProvider {
    constructor(createChatBotMessage, setStateFunc, createClientMessage) {
      this.createChatBotMessage = createChatBotMessage;
      this.setState = setStateFunc;
      this.createClientMessage = createClientMessage;
    }

    // called when user answers a question; save answer & ask next question or predict
    handleAnswer = async (field, value, nextQuestion) => {
      this.setState(prev => ({
        ...prev,
        answers: {
          ...prev.answers,
          [field]: value,
        }
      }));

      if (nextQuestion) {
        const msg = this.createChatBotMessage(nextQuestion);
        this.setState(prev => ({
          ...prev,
          messages: [...prev.messages, msg],
        }));
      } else {
        // no more questions — call backend predict
        const answers = this.getAnswers();

        // Show loading message
        const loadingMsg = this.createChatBotMessage("Predicting... Please wait.");
        this.setState(prev => ({
          ...prev,
          messages: [...prev.messages, loadingMsg],
        }));

        try {
          const response = await fetch('http://localhost:8000/predict', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(answers),
          });
          const data = await response.json();

          const resultText = data.prediction
            ? `High Risk! (${(data.probability * 100).toFixed(1)}% probability)`
            : `Low Risk (${(data.probability * 100).toFixed(1)}% probability)`;

          const resultMsg = this.createChatBotMessage(`Prediction result: ${resultText}`);

          this.setState(prev => ({
            ...prev,
            messages: [...prev.messages, resultMsg],
          }));

          // Save prediction to parent state to optionally use elsewhere
          setPredictionResult(data);

        } catch (error) {
          const errorMsg = this.createChatBotMessage("Prediction failed. Please try again.");
          this.setState(prev => ({
            ...prev,
            messages: [...prev.messages, errorMsg],
          }));
        }
      }
    }

    getAnswers() {
      let answers = this.state?.answers || {};
      // Provide default values for missing fields if needed
      return {
        age: Number(answers.age) || 30,
        gender: answers.gender || 'Female',
        bmi: Number(answers.bmi) || 25.0,
        hbA1c_level: Number(answers.hbA1c_level) || 5.7,
        blood_glucose_level: Number(answers.blood_glucose_level) || 120,
        hypertension: answers.hypertension === 'yes' ? 1 : 0,
        heart_disease: answers.heart_disease === 'yes' ? 1 : 0,
        smoking_history: answers.smoking_history || 'never',
      };
    }
  }

  // -------------------- MessageParser --------------------
  class MessageParser {
    constructor(actionProvider) {
      this.actionProvider = actionProvider;
    }

    parse(message) {
      const lower = message.toLowerCase();

      // Check current question and route answers accordingly:
      // We'll store in state which question we are on

      // Get last bot message from state:
      const state = this.actionProvider.state;
      const messages = state?.messages || [];
      const lastBotMessage = messages.length ? messages[messages.length - 1].text : '';

      // Simple question-answer flow by matching last bot message:

      if (lastBotMessage.includes("How old are you")) {
        this.actionProvider.handleAnswer('age', message, "What's your gender? (Female, Male, Other)");
      } else if (lastBotMessage.includes("What's your gender")) {
        if (['female', 'male', 'other'].includes(lower)) {
          this.actionProvider.handleAnswer('gender', message, "What's your BMI? (e.g., 25.5)");
        } else {
          this.actionProvider.setState(prev => ({
            ...prev,
            messages: [...prev.messages, this.actionProvider.createChatBotMessage("Please type Female, Male, or Other.")]
          }));
        }
      } else if (lastBotMessage.includes("What's your BMI")) {
        const val = parseFloat(message);
        if (!isNaN(val) && val >= 10 && val <= 50) {
          this.actionProvider.handleAnswer('bmi', val, "What's your HbA1c level (%)? (e.g., 5.7)");
        } else {
          this.actionProvider.setState(prev => ({
            ...prev,
            messages: [...prev.messages, this.actionProvider.createChatBotMessage("Please enter a valid BMI between 10 and 50.")]
          }));
        }
      } else if (lastBotMessage.includes("HbA1c level")) {
        const val = parseFloat(message);
        if (!isNaN(val) && val >= 3 && val <= 15) {
          this.actionProvider.handleAnswer('hbA1c_level', val, "What's your Blood Glucose Level (mg/dL)? (e.g., 120)");
        } else {
          this.actionProvider.setState(prev => ({
            ...prev,
            messages: [...prev.messages, this.actionProvider.createChatBotMessage("Please enter a valid HbA1c level between 3 and 15.")]
          }));
        }
      } else if (lastBotMessage.includes("Blood Glucose Level")) {
        const val = parseInt(message);
        if (!isNaN(val) && val >= 50 && val <= 300) {
          this.actionProvider.handleAnswer('blood_glucose_level', val, "Do you have hypertension? (yes/no)");
        } else {
          this.actionProvider.setState(prev => ({
            ...prev,
            messages: [...prev.messages, this.actionProvider.createChatBotMessage("Please enter a valid Blood Glucose Level between 50 and 300.")]
          }));
        }
      } else if (lastBotMessage.includes("hypertension")) {
        if (['yes', 'no'].includes(lower)) {
          this.actionProvider.handleAnswer('hypertension', lower, "Do you have heart disease? (yes/no)");
        } else {
          this.actionProvider.setState(prev => ({
            ...prev,
            messages: [...prev.messages, this.actionProvider.createChatBotMessage("Please answer 'yes' or 'no'.")]
          }));
        }
      } else if (lastBotMessage.includes("heart disease")) {
        if (['yes', 'no'].includes(lower)) {
          this.actionProvider.handleAnswer('heart_disease', lower, "What's your smoking history? (never, former, current, not current, ever)");
        } else {
          this.actionProvider.setState(prev => ({
            ...prev,
            messages: [...prev.messages, this.actionProvider.createChatBotMessage("Please answer 'yes' or 'no'.")]
          }));
        }
      } else if (lastBotMessage.includes("smoking history")) {
        const valid = ['never', 'former', 'current', 'not current', 'ever'];
        if (valid.includes(lower)) {
          this.actionProvider.handleAnswer('smoking_history', lower, null);
        } else {
          this.actionProvider.setState(prev => ({
            ...prev,
            messages: [...prev.messages, this.actionProvider.createChatBotMessage(`Please enter one of: ${valid.join(', ')}`)]
          }));
        }
      } else {
        // If conversation just started or unknown, start first question
        const startMsg = this.actionProvider.createChatBotMessage("Hi! Let's predict your diabetes risk. How old are you?");
        this.actionProvider.setState(prev => ({
          ...prev,
          messages: [...prev.messages, startMsg]
        }));
      }
    }
  }

  // -------------------- Config --------------------
  const config = {
    botName: "DiabetesBot",
    initialMessages: [],
    state: {
      answers: {}
    },
    customStyles: {
      botMessageBox: {
        backgroundColor: "#376B7E",
      },
      chatButton: {
        backgroundColor: "#5ccc9d",
      },
    },
    // disable user input until the bot asks something
    // handled manually in MessageParser
  };

  return (
    <div style={{ maxWidth: 500, margin: '20px auto' }}>
      <h2>Diabetes Risk Prediction Chatbot</h2>
      <Chatbot
        config={config}
        actionProvider={ActionProvider}
        messageParser={MessageParser}
        key="chatbot"
      />

      {predictionResult && (
        <div style={{ marginTop: 20, padding: 10, border: '1px solid #ccc' }}>
          <h3>Summary</h3>
          <p><strong>Risk Level:</strong> {predictionResult.interpretation || (predictionResult.prediction ? "High Risk" : "Low Risk")}</p>
          <p><strong>Probability:</strong> {(predictionResult.probability * 100).toFixed(1)}%</p>
          <p>
            {predictionResult.prediction
              ? "We recommend consulting with a healthcare professional for further evaluation."
              : "Maintain healthy habits to keep your risk low."}
          </p>
        </div>
      )}
    </div>
  );
}

export default Prediction;
